from __future__ import annotations

def tropical_stereo(x: float) -> float:
    """Return max(2x,x)-max(x,0)."""
    return max(2.0*x, x) - max(x, 0.0)

values: tuple[float, ...] = (-3.0, -1.0, 0.0, 2.0, 5.0)
print("x       S(x)    residual")
for x in values:
    y = tropical_stereo(x)
    print(f"{x:6.1f}  {y:6.1f}  {y-x:+.1e}")

from __future__ import annotations

def tropical_stereo_at(p: float, x: float) -> float:
    """Return max(2x,x+p)-max(x,p)."""
    return max(2.0*x, x+p) - max(x, p)

poles: tuple[float, ...] = (-4.0, 0.0, 1.5, 6.0)
xs: tuple[float, ...] = (-3.0, 0.0, 2.0, 8.0)
for p in poles:
    row = [tropical_stereo_at(p, x) for x in xs]
    print(f"p={p:5.1f}: {row}")
assert all(tropical_stereo_at(p, x) == x for p in poles for x in xs)

