from __future__ import annotations

def reduce_pole_family(p: float) -> tuple[float, float]:
    """Return slope and intercept after cancelling the common max factor.

    The identity max(2x,x+p)=x+max(x,p) makes every finite p reduce to x.
    """
    _ = p
    return (1.0, 0.0)

def reduced_value(p: float, x: float) -> float:
    slope, intercept = reduce_pole_family(p)
    return slope*x+intercept

from __future__ import annotations

from collections.abc import Iterable

def audit_grid(poles: Iterable[float], xs: Iterable[float], tol: float=1e-12) -> list[tuple[float,float,float]]:
    """Return (p,x,residual) records whose identity residual exceeds tol."""
    values = tuple(xs)
    failures: list[tuple[float,float,float]] = []
    for p in poles:
        for x in values:
            residual = max(2.0*x, x+p)-max(x,p)-x
            if abs(residual) > tol:
                failures.append((p,x,residual))
    return failures

